const debug = process.env.SCRIPTC_ABSENT_ENV_DEBUG !== undefined;
const traced = "SCRIPTC_ABSENT_ENV_TRACE" in process.env;
const level = Object.prototype.hasOwnProperty.call(process.env, "SCRIPTC_ABSENT_ENV_LEVEL")
  ? process.env.SCRIPTC_ABSENT_ENV_LEVEL
  : "info";
class Logger {
  constructor(name) {
    this.name = name;
  }
  line(text) {
    return `[${level}] ${this.name}: ${text}`;
  }
}
function describe(prefix) {
  return `${prefix}: debug ${debug}, traced ${traced}, level ${level}`;
}
const VERSION = "1.2.0";
module.exports = { describe, Logger, DEBUG: debug, TRACED: traced, VERSION };
